class TestStatus(OpenEnum):
    """
    - TEST_STATUS_UNSPECIFIED: Invalid value.
     - TEST_STATUS_ACTIVE: Test is active.
     - TEST_STATUS_PAUSED: Test is paused.
     - TEST_STATUS_DELETED: Test is deleted. Not user settable.
     - TEST_STATUS_PREVIEW: Test is preview
    """

    TEST_STATUS_UNSPECIFIED = "TEST_STATUS_UNSPECIFIED"
    TEST_STATUS_ACTIVE = "TEST_STATUS_ACTIVE"
    TEST_STATUS_PAUSED = "TEST_STATUS_PAUSED"
    TEST_STATUS_DELETED = "TEST_STATUS_DELETED"
    TEST_STATUS_PREVIEW = "TEST_STATUS_PREVIEW"


class TestThroughputSettings(KentikModel):
    bandwidth: int | None = None
    """
    (optional) Target bandwidth in Mbps, if no bandwidth is specified, the test will measure the maximum bandwidth for TCP and 10Mbps for UDP
    """
    duration: int | None = None
    """
    Duration of the test in seconds
    """
    omit: int | None = None
    """
    (optional) Number of seconds to omit from the start of the test
    """
    port: int | None = None
    """
    Target port for TCP or UDP throughput task (the port the target server is listening on)
    """
    protocol: str | None = None
    """
    Transport protocol to use (tcp | udp)
    """


class TestTraceSettings(KentikModel):
    count: int | None = None
    """
    Number of probe packets to send in one iteration
    """
    delay: float | None = None
    """
    Inter-probe delay in milliseconds
    """
    dscp: int | None = None
    """
    DSCP code to be set in IP header of probe packets
    """
    limit: int | None = None
    """
    Maximum number of hops to probe (i.e. maximum TTL)
    """
    mtu: bool | None = None
    """
    Enable MTU in trace results
    """
    port: int | None = None
    """
    Target port for TCP or UDP probes (ignored for ICMP)
    """
    protocol: str | None = None
    """
    Transport protocol to use (icmp | tcp | udp)
    """
    timeout: int | None = None
    """
    Timeout in milliseconds for execution of the task
    """


class UrlTest(KentikModel):
    body: str | None = None
    """
    HTTP request body
    """
    headers: dict[str, str] | None = None
    """
    Map of HTTP header values keyed by header names
    """
    ignore_tls_errors: Annotated[bool | None, Field(alias="ignoreTlsErrors")] = None
    """
    Boolean indicating whether to ignore TLS certificate verification errors
    """
    method: str | None = None
    """
    HTTP method to use (GET | HEAD | PATCH | POST | PUT)
    """
    target: str | None = None
    """
    HTTP or HTTPS URL to request
    """
    timeout: int | None = None
    """
    HTTP transaction timeout (in milliseconds)
    """


class UserInfo(KentikModel):
    email: str | None = None
    """
    E-mail address of the user
    """
    full_name: Annotated[str | None, Field(alias="fullName")] = None
    """
    Full name of the user
    """
    id: str | None = None
    """
    Unique system generated ID
    """
